// zone and device_channel row-level security and integrity — generated by `pnpm gen:migration`
// (02-architecture §4, 04-testing §3); E4 platform binding cases added (D-29, alerts checkbox).
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  client,
  createDatabase,
  device,
  deviceChannel,
  eq,
  inActorTransaction,
  migrateUp,
  site,
  zone,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const clientB = randomUUID();
const siteA = randomUUID();
const siteA2 = randomUUID();
const siteB = randomUUID();
const gateA = randomUUID();
const gateA2 = randomUUID();
const deviceA = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const system: DbActor = { id: randomUUID(), kind: 'system', clientIds: [], roles: ['system'] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const userOfB: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientB] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const siteOf = (id: string, clientId: string, projectId: string, runningNo = 1) => ({
  id,
  clientId,
  projectId,
  countryCode: 'ES',
  cityCode: 'MAD',
  cityName: 'Madrid',
  runningNo,
  name: 'Site 001',
  standard: 'L' as const,
});
const zoneOf = (
  clientId: string,
  siteId: string,
  name: string,
  more: Partial<typeof zone.$inferInsert> = {},
) => ({
  id: randomUUID(),
  clientId,
  siteId,
  kind: 'area' as const,
  platformRef: randomUUID(),
  name,
  ...more,
});
let testDb: TestDatabase;
let database: Database;

type Tx = Parameters<Parameters<typeof inActorTransaction>[2]>[0];
const asStaff = <T>(work: (tx: Tx) => Promise<T>) => inActorTransaction(database.db, staff, work);
const visibleTo = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) =>
    (await tx.select().from(zone)).map((r) => r.name).sort(),
  );
const channelsSeenBy = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) => (await tx.select().from(deviceChannel)).length);

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await asStaff(async (tx) => {
    await tx.insert(client).values([
      { id: clientA, shortCode: 'CLIENTA', name: 'Client A' },
      { id: clientB, shortCode: 'CLIENTB', name: 'Client B' },
    ]);
    await tx
      .insert(site)
      .values([
        siteOf(siteA, clientA, 'CLIENTA-ES-MAD-001'),
        siteOf(siteA2, clientA, 'CLIENTA-ES-MAD-002', 2),
        siteOf(siteB, clientB, 'CLIENTB-ES-MAD-001'),
      ]);
    await tx
      .insert(zone)
      .values([
        zoneOf(clientA, siteA, 'Store A1', { visibility: 'client' }),
        zoneOf(clientA, siteA, 'Gate 1', { id: gateA, kind: 'gate', entrance: true }),
        zoneOf(clientA, siteA2, 'Gate 2', { id: gateA2, kind: 'gate' }),
        zoneOf(clientB, siteB, 'Store B1'),
      ]);
    await tx
      .insert(device)
      .values({ id: deviceA, clientId: clientA, siteId: siteA, sn: 'SN-0001', model: 'G6' });
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff see every zone', async () => {
  expect(await visibleTo(staff)).toEqual(['Gate 1', 'Gate 2', 'Store A1', 'Store B1']);
});

it('a client sees only its own zones marked for clients', async () => {
  expect(await visibleTo(userOfA)).toEqual(['Store A1']);
  expect(await visibleTo(userOfB)).toEqual([]);
});

it('a partner sees nothing until a partner policy exists', async () => {
  expect(await visibleTo(partnerOfA)).toEqual([]);
});

it('a client cannot write', async () => {
  await expect(
    inActorTransaction(database.db, userOfA, (tx) => tx.insert(zone).values(zoneOf(clientA, siteA, 'X'))),
  ).rejects.toThrow();
});

it("a zone is an area or a gate of its own client's project; only a gate is an entrance", async () => {
  for (const bad of [
    { siteId: siteB },
    { kind: 'door' as 'gate' },
    { entrance: true },
    { name: ' ' },
    { platformRef: '' },
  ]) {
    await expect(
      asStaff((tx) => tx.insert(zone).values(zoneOf(clientA, siteA, 'Bad', bad))),
    ).rejects.toThrow();
  }
});

it('a platform zone is in a project once while active, and an archived one frees it', async () => {
  const platformRef = randomUUID();
  await asStaff((tx) => tx.insert(zone).values(zoneOf(clientA, siteA, 'Store A2', { platformRef })));
  await expect(
    asStaff((tx) => tx.insert(zone).values(zoneOf(clientA, siteA, 'Store A2 again', { platformRef }))),
  ).rejects.toThrow();
  await asStaff((tx) =>
    tx.update(zone).set({ archivedAt: new Date() }).where(eq(zone.platformRef, platformRef)),
  );
  await asStaff((tx) => tx.insert(zone).values(zoneOf(clientA, siteA, 'Store A2 reopened', { platformRef })));
});

it('a channel counts a gate of the same project; staff and the sync see channels, clients do not', async () => {
  const channel = (channelNo: number, zoneId: string | null) => ({
    deviceId: deviceA,
    channelNo,
    clientId: clientA,
    siteId: siteA,
    zoneId,
  });
  await inActorTransaction(database.db, system, (tx) =>
    tx.insert(deviceChannel).values([channel(1, gateA), channel(2, null)]),
  );
  await expect(asStaff((tx) => tx.insert(deviceChannel).values(channel(3, gateA2)))).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(deviceChannel).values({ ...channel(4, null), siteId: siteA2 })),
  ).rejects.toThrow();
  expect(await channelsSeenBy(staff)).toBe(2);
  expect(await channelsSeenBy(system)).toBe(2);
  expect(await channelsSeenBy(userOfA)).toBe(0);
  expect(await channelsSeenBy(partnerOfA)).toBe(0);
});

it('offline_since is set exactly while the platform says offline', async () => {
  const set = (values: Partial<typeof device.$inferInsert>) =>
    asStaff((tx) => tx.update(device).set(values).where(eq(device.id, deviceA)));
  await expect(set({ platformStatus: 'offline' })).rejects.toThrow();
  await expect(set({ platformStatus: 'online', offlineSince: new Date() })).rejects.toThrow();
  await expect(set({ platformStatus: 'broken' as 'online' })).rejects.toThrow();
  await set({ platformStatus: 'offline', offlineSince: new Date(), syncedAt: new Date() });
  await set({ platformStatus: 'online', offlineSince: null });
});

it('a project is one mall on the platform; offline alerts are off until someone ticks the box', async () => {
  const [row] = await asStaff((tx) => tx.select().from(site).where(eq(site.id, siteA)));
  expect(row?.deviceAlertsEnabled).toBe(false);
  await asStaff((tx) => tx.update(site).set({ platformRef: 'mall-a' }).where(eq(site.id, siteA)));
  await expect(
    asStaff((tx) => tx.update(site).set({ platformRef: 'mall-a' }).where(eq(site.id, siteB))),
  ).rejects.toThrow();
  await asStaff((tx) => tx.update(site).set({ deviceAlertsEnabled: true }).where(eq(site.id, siteA)));
});
